// 72 Framework-Delta-Dokumente (control-mapping Engine) — zu den 57 Basis-Policies ergänzt.
import { DELTA_TEMPLATES } from "./deltaDocuments";
const ALL_POLICY_TEMPLATES: PolicyTemplate[] = [...POLICY_TEMPLATES, ...DELTA_TEMPLATES];
export default ALL_POLICY_TEMPLATES;

const CURATED_CATEGORIES = [
  { de: "Framework-Delta-Dokumente", en: "Framework Delta Documents" },
  { de: "Governance & Risiko", en: "Governance & Risk" },
  { de: "Asset-Management", en: "Asset Management" },
  { de: "Zugriffssteuerung", en: "Access Control" },
  { de: "Netzwerk- & Systemsicherheit", en: "Network & System Security" },
  { de: "Geräte & Medien", en: "Device & Media" },
  { de: "Überwachung & Erkennung", en: "Monitoring & Detection" },
  { de: "Vorfallmanagement", en: "Incident Management" },
  { de: "Geschäftskontinuität", en: "Business Continuity" },
  { de: "Datenschutz", en: "Data Protection" },
  { de: "Lieferantensicherheit", en: "Supplier Security" },
  { de: "Personal & Bewusstsein", en: "People & Awareness" },
  { de: "Entwicklung & Änderung", en: "Development & Change" },
  { de: "Physische Sicherheit", en: "Physical Security" },
  { de: "Künstliche Intelligenz", en: "Artificial Intelligence" },
];

/**
 * Kategorien für den Filter: kuratierte Reihenfolge, danach jede weitere
 * Kategorie, die in einer Vorlage vorkommt. Vorher fehlten vier Kategorien
 * („ISMS-Grundlagendokumente", „Risikomanagement-Nachweise", „OT/ICS-Sicherheit",
 * „Ergänzende Richtlinien und Nachweise") — deren Dokumente (u. a. SoA, Scope,
 * RTP, Risikobewertungsbericht) waren über den Kategorienfilter nicht erreichbar.
 */
export const POLICY_CATEGORIES: { de: string; en: string }[] = (() => {
  const out = [...CURATED_CATEGORIES];
  for (const t of ALL_POLICY_TEMPLATES) {
    if (!out.some(c => c.de === t.category)) out.push({ de: t.category, en: t.categoryEn || t.category });
  }
  return out;
})();
